45	            dados.getDescontoCupom(),
46	            dados.getFrete(),
47	            dados.getPrazoEntregaDias(),
48	            dados.getSeguro(),
49	            dados.getAjustePagamento(),
50	            dados.getTotalFinal(),
51	            dados.getParcelas(),
52	            dados.getValorParcela(),
53	            dados.getCreditoProximaCompra(),
54	            dados.getBrinde()
55	        );
56	    }
57	
58	    private void calcularSubtotalProdutos(DadosCalculo dados) {
59	        BigDecimal subtotal = dados.getItens().stream()
60	            .map(item -> item.precoUnitario()
61	                .multiply(new BigDecimal(item.quantidade()))
62	                .setScale(2, RoundingMode.HALF_EVEN))
63	            .reduce(BigDecimal.ZERO, BigDecimal::add);
64	
65	        dados.setSubtotalProdutos(subtotal);
66	    }
