78	
79	        if (nivelClube.temFreteGratis()) {
80	            frete = new BigDecimal("0.00");
81	        }
82	
83	        dados.setFrete(frete);
84	        dados.setPrazoEntregaDias(modalidade.getPrazoEntregaDias());
