95	    private void calcularTotalPedido(DadosCalculo dados) {
96	        BigDecimal total = dados.getSubtotalProdutos()
97	            .subtract(dados.getDescontoCupom())
98	            .add(dados.getFrete())
99	            .add(dados.getSeguro());
100	
101	        dados.setTotalPedido(total);
