3	import com.loja.checkout.domain.NivelClube;
4	import com.loja.checkout.domain.Regiao;
5	import com.loja.checkout.domain.cupom.Cupom;
6	import com.loja.checkout.domain.cupom.CupomFactory;
7	import com.loja.checkout.domain.entrega.ModalidadeEntrega;
8	import com.loja.checkout.domain.entrega.ModalidadeEntregaFactory;
9	import com.loja.checkout.domain.pagamento.FormaPagamento;
10	import com.loja.checkout.domain.pagamento.FormaPagamentoFactory;
11	import com.loja.checkout.model.dto.ErroResponse;
12	import com.loja.checkout.model.dto.ItemPedido;
13	import com.loja.checkout.model.dto.PedidoRequest;
14	import com.loja.checkout.model.dto.ResumoResponse;
15	import com.loja.checkout.service.CalculadoraResumo;
16	import org.springframework.http.ResponseEntity;
17	import org.springframework.web.bind.annotation.PostMapping;
18	import org.springframework.web.bind.annotation.RequestBody;
19	import org.springframework.web.bind.annotation.RequestMapping;
20	import org.springframework.web.bind.annotation.RestController;
21	
22	import java.math.BigDecimal;
23	
24	@RestController
25	@RequestMapping("/checkout")
26	public class CheckoutController {
27	
28	    private final CalculadoraResumo calculadoraResumo;
29	
30	    public CheckoutController(CalculadoraResumo calculadoraResumo) {
31	        this.calculadoraResumo = calculadoraResumo;
32	    }
33	
34	    @PostMapping("/resumo")
35	    public ResponseEntity<?> calcularResumo(@RequestBody PedidoRequest pedido) {
36	
37	        String erro = validarPedido(pedido);
38	        if (erro != null) {
39	            return ResponseEntity.badRequest().body(new ErroResponse(erro));
40	        }
41	
42	        NivelClube nivelClube;
43	        try {
44	            nivelClube = NivelClube.valueOf(pedido.nivelClube());
45	        } catch (Exception e) {
46	            return ResponseEntity.badRequest().body(new ErroResponse("NIVEL_CLUBE_INVALIDO"));
47	        }
48	
49	        Regiao regiao;
50	        try {
51	            regiao = Regiao.valueOf(pedido.regiao());
52	        } catch (Exception e) {
53	            return ResponseEntity.badRequest().body(new ErroResponse("REGIAO_INVALIDA"));
54	        }
55	
56	        if (!ModalidadeEntregaFactory.existe(pedido.modalidadeEntrega())) {
57	            return ResponseEntity.badRequest().body(new ErroResponse("MODALIDADE_INVALIDA"));
58	        }
59	
60	        ModalidadeEntrega modalidadeEntrega = ModalidadeEntregaFactory.criar(pedido.modalidadeEntrega());
61	
62	        if (!modalidadeEntrega.estaDisponivel(pedido.itens())) {
63	            return ResponseEntity.badRequest().body(new ErroResponse("MODALIDADE_INDISPONIVEL"));
64	        }
65	
66	        Cupom cupom = null;
67	        if (pedido.cupom() != null && !pedido.cupom().isEmpty()) {
68	            if (!CupomFactory.existe(pedido.cupom())) {
69	                return ResponseEntity.badRequest().body(new ErroResponse("CUPOM_INVALIDO"));
70	            }
71	            cupom = CupomFactory.criar(pedido.cupom());
72	        }
73	
74	        if (!FormaPagamentoFactory.existe(pedido.formaPagamento())) {
75	            return ResponseEntity.badRequest().body(new ErroResponse("FORMA_PAGAMENTO_INVALIDA"));
76	        }
77	
78	        FormaPagamento formaPagamento = FormaPagamentoFactory.criar(pedido.formaPagamento());
79	
80	        int numeroParcelas = pedido.parcelas() != null ? pedido.parcelas() : 1;
81	
82	        if (!formaPagamento.parcelamentoValido(numeroParcelas)) {
83	            return ResponseEntity.badRequest().body(new ErroResponse("PARCELAMENTO_INVALIDO"));
84	        }
85	
86	        BigDecimal subtotalProdutos = pedido.itens().stream()
87	            .map(item -> item.precoUnitario().multiply(new BigDecimal(item.quantidade())))
88	            .reduce(BigDecimal.ZERO, BigDecimal::add);
89	
90	        BigDecimal frete = modalidadeEntrega.calcularFrete(pedido.itens());
91	        if (nivelClube.temFreteGratis()) {
92	            frete = BigDecimal.ZERO;
93	        }
94	
95	        BigDecimal descontoCupom = BigDecimal.ZERO;
96	        if (cupom != null) {
97	            com.loja.checkout.domain.DadosCalculo dadosTemp = new com.loja.checkout.domain.DadosCalculo();
98	            dadosTemp.setItens(pedido.itens());
99	            dadosTemp.setSubtotalProdutos(subtotalProdutos);
100	            dadosTemp.setFrete(frete);
101	
102	            if (!cupom.podeAplicar(dadosTemp)) {
103	                return ResponseEntity.badRequest().body(new ErroResponse("CUPOM_NAO_APLICAVEL"));
104	            }
105	        }
106	
107	        Regiao regiaoEnum = regiao;
108	        BigDecimal seguro = subtotalProdutos.multiply(regiaoEnum.getTaxa());
109	        BigDecimal totalPedido = subtotalProdutos.subtract(descontoCupom).add(frete).add(seguro);
110	
111	        if (!formaPagamento.estaDisponivel(totalPedido)) {
112	            return ResponseEntity.badRequest().body(new ErroResponse("FORMA_PAGAMENTO_INDISPONIVEL"));
113	        }
114	
115	        ResumoResponse resumo = calculadoraResumo.calcular(
116	            pedido,
117	            modalidadeEntrega,
118	            cupom,
119	            formaPagamento,
120	            nivelClube,
121	            regiao
122	        );
123	
124	        return ResponseEntity.ok(resumo);
125	    }
126	
127	    private String validarPedido(PedidoRequest pedido) {
128	        if (pedido.itens() == null || pedido.itens().isEmpty()) {
129	            return "PEDIDO_INVALIDO";
130	        }
131	
132	        for (ItemPedido item : pedido.itens()) {
133	            if (item.precoUnitario() == null || item.precoUnitario().compareTo(BigDecimal.ZERO) <= 0) {
134	                return "PEDIDO_INVALIDO";
135	            }
136	            if (item.quantidade() == null || item.quantidade() <= 0) {
137	                return "PEDIDO_INVALIDO";
138	            }
139	            if (item.pesoKg() == null || item.pesoKg().compareTo(BigDecimal.ZERO) <= 0) {
140	                return "PEDIDO_INVALIDO";
141	            }
142	        }
143	
144	        if (pedido.nivelClube() == null || pedido.nivelClube().isEmpty()) {
145	            return "NIVEL_CLUBE_INVALIDO";
146	        }
147	
148	        if (pedido.regiao() == null || pedido.regiao().isEmpty()) {
149	            return "REGIAO_INVALIDA";
150	        }
151	
152	        if (pedido.modalidadeEntrega() == null || pedido.modalidadeEntrega().isEmpty()) {
153	            return "MODALIDADE_INVALIDA";
154	        }
155	
156	        if (pedido.formaPagamento() == null || pedido.formaPagamento().isEmpty()) {
157	            return "FORMA_PAGAMENTO_INVALIDA";
158	        }
159	
160	        return null;
161	    }
162	}
