1	package com.loja.checkout.domain.pagamento;
2	
3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	
6	public class Cartao implements FormaPagamento {
7	
8	    @Override
9	    public boolean estaDisponivel(BigDecimal totalPedido) {
10	        return true;
11	    }
12	
13	    @Override
14	    public boolean parcelamentoValido(int numeroParcelas) {
15	        return numeroParcelas >= 1 && numeroParcelas <= 12;
16	    }
17	
18	    @Override
19	    public BigDecimal calcularAjuste(BigDecimal totalPedido, int numeroParcelas) {
20	        if (numeroParcelas <= 3) {
21	            return new BigDecimal("0.00");
22	        }
23	
24	        BigDecimal taxa = new BigDecimal("0.0199");
25	
26	        BigDecimal umMaisTaxa = BigDecimal.ONE.add(taxa);
27	        BigDecimal fatorPotencia = BigDecimal.ONE.divide(
28	            umMaisTaxa.pow(numeroParcelas),
29	            10,
30	            RoundingMode.HALF_EVEN
31	        );
32	
33	        BigDecimal divisor = BigDecimal.ONE.subtract(fatorPotencia);
34	
35	        BigDecimal parcela = totalPedido
36	            .multiply(taxa)
37	            .divide(divisor, 2, RoundingMode.HALF_EVEN);
38	
39	        BigDecimal totalComJuros = parcela.multiply(new BigDecimal(numeroParcelas));
40	
41	        return totalComJuros.subtract(totalPedido);
42	    }
43	
44	    @Override
45	    public BigDecimal calcularValorParcela(BigDecimal totalFinal, int numeroParcelas) {
46	        return totalFinal
47	            .divide(new BigDecimal(numeroParcelas), 2, RoundingMode.HALF_EVEN);
48	    }
49	}
