37	        String erro = validarPedido(pedido);
38	        if (erro != null) {
39	            return ResponseEntity.badRequest().body(new ErroResponse(erro));
40	        }
41	
42	        NivelClube nivelClube;
43	        try {
44	            nivelClube = NivelClube.valueOf(pedido.nivelClube());
